/**
 * What ProductDTO promises about itself, checked here as a courtesy.
 *
 * The server enforces these when the row is written - that is what
 * makes them true. This is so a form can say what is wrong before
 * the request, in the domain's own words.
 *
 * @returns the promises this value breaks, empty when it keeps them
 */
export function violations(product: ProductDTO | null | undefined): string[] {
    const broken: string[] = [];
    if (product == null) return broken;
    if (product.price != null && Number(product.price) < 0) {
        broken.push('price must not be negative');
    }
    return broken;
}

/** Whether ProductDTO keeps every promise it makes. */
export function isValid(product: ProductDTO | null | undefined): boolean {
    return violations(product).length === 0;
}
